'use strict';

const OP_EQUAL = 0;
const OP_DELETE = 1;
const OP_INSERT = 2;
const OP_NAMES = ['equal', 'delete', 'insert'];

/**
 * Map both line arrays to integer ids so the hot loops compare numbers.
 */
function internLines(a, b) {
  const ids = new Map();
  const encode = (lines) => {
    const out = new Int32Array(lines.length);
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      let id = ids.get(line);
      if (id === undefined) {
        id = ids.size;
        ids.set(line, id);
      }
      out[i] = id;
    }
    return out;
  };
  return [encode(a), encode(b)];
}

/**
 * Linear-space Myers diff (divide and conquer on the middle snake).
 * Emits raw ops as (kind, index) pairs into `ops` in order; the index is into
 * A for equal/delete and into B for insert.
 */
function myers(A, B, ops) {
  const size = 2 * (Math.ceil((A.length + B.length) / 2) + 1);
  const vf = new Int32Array(size);
  const vb = new Int32Array(size);

  const emit = (kind, index) => {
    ops.push(kind, index);
  };

