  const s = diffLines(a, b);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  assert.equal(s.filter((e) => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  for (let i = 1; i < s.length; i++) assert.ok(!(s[i - 1].op === 'insert' && s[i].op === 'delete'));
  assert.deepEqual(diffLines(a, b), s);
  const ctx = rnd(4);
  const hunks = unifiedHunks(a, b, { context: ctx });
  if (s.every((e) => e.op === 'equal')) assert.deepEqual(hunks, []);
  assert.deepEqual(applyHunks(a, hunks), b);
  for (const h of hunks) {
    // coordinate check vs whole arrays
    const old = h.lines.filter((l) => l[0] !== '+').map((l) => l.slice(1));
    const nw = h.lines.filter((l) => l[0] !== '-').map((l) => l.slice(1));
    const os = h.oldLines ? h.oldStart - 1 : h.oldStart;
    const ns = h.newLines ? h.newStart - 1 : h.newStart;
    assert.deepEqual(a.slice(os, os + h.oldLines), old);
    assert.deepEqual(b.slice(ns, ns + h.newLines), nw);
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}

// perf
const big = Array.from({ length: 20000 }, (_, i) => `line ${i % 50}`);
const big2 = big.slice();
for (let i = 0; i < 40; i++) big2[rnd(20000)] = 'changed ' + i;
big2.splice(100, 0, 'ins');
let t0 = Date.now();
const hb = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, hb), big2);
console.log('scattered ms', Date.now() - t0);
t0 = Date.now(); diffLines(big, big.slice()); console.log('equal ms', Date.now() - t0);
const rep = Array(20000).fill('x');
t0 = Date.now(); const r = diffLines(rep, rep.slice(0, 19990).concat(['y'])); console.log('repetitive ms', Date.now() - t0, r.length);
t0 = Date.now(); diffLines(Array.from({ length: 2000 }, (_, i) => 'a' + i), Array.from({ length: 2000 }, (_, i) => 'b' + i)); console.log('disjoint 2k ms', Date.now() - t0);

// apply errors
assert.throws(() => applyHunks(['a'], [{ oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: [' b'] }]), /hunk 0 does not apply/);
const h2 = unifiedHunks(['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i'], ['A', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'I'], { context: 1 });
assert.equal(h2.length, 2);
assert.throws(() => applyHunks(['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i'], [h2[1], h2[0]]), /hunk 1 does not apply/);
assert.throws(() => applyHunks(['a'], [{ oldStart: 1, oldLines: 1, newStart: 2, newLines: 1, lines: ['-a', '+b'] }]), /hunk 0 does not apply/);
console.log(JSON.stringify(unifiedHunks(['a', 'b'], ['x', 'a', 'b'], { context: 0 })), JSON.stringify(unifiedHunks(['a', 'b'], ['b'], { context: 0 })));
console.log('ok');
